import zlib

def size(text):
    return len(zlib.compress(text.encode('utf-8'), 9))

def extra(A, B):
    # A 에 맞춰진 압축기가 B 조각을 줄이는 데 더 쓴 바이트
    return size(A + B) - size(A)

ko = '나는 오늘 아침에 학교에 갔다. 친구와 함께 점심을 먹고 도서관에서 책을 읽었다. ' * 30
en = 'I went to school this morning. I had lunch with a friend and read a book in the library. ' * 30
ko2 = '어제 저녁에는 가족과 함께 공원에 가서 산책을 했다. 날씨가 맑아서 기분이 좋았다. '
en2 = 'Yesterday evening I took a walk in the park with my family. The weather was nice. '

for a_name, A in (('ko', ko), ('en', en)):
    for b_name, B in (('ko2', ko2), ('en2', en2)):
        print(a_name, '+', b_name, extra(A, B))
# ko + ko2 59 / ko + en2 72 / en + ko2 109 / en + en2 46

import math

def entropy(p):
    return sum(-pi * math.log2(pi) for pi in p if pi > 0)

def cross_entropy(p, q):
    # p: 실제 확률(너비), q: 부호를 맞춘 확률(높이 = -log2 q)
    return sum(-pi * math.log2(qi) for pi, qi in zip(p, q) if pi > 0)

old = [1/2, 1/4, 1/8, 1/8]   # 위, 아래, 왼쪽, 오른쪽 (옛 계획)
new = [1/8, 1/8, 1/4, 1/2]   # 바뀐 계획
print(entropy(old))              # 1.75
print(cross_entropy(new, old))   # 2.625  옛 부호를 새 상황에서
print(entropy(new))              # 1.75   새 부호를 새로 짰다면
